import {View} from 'react-native';
import {UnitInput} from '@/components/nyc-tron/ui/components/shell/UnitInput';
import {validateMotionVector,type MotionVector3} from '@/components/nyc-tron/ui/components/forge/motion/motion-settings';
export interface MotionVectorFieldsProps {readonly label:string;readonly value:MotionVector3;readonly onCommit:(value:MotionVector3)=>void;readonly min?:number;readonly max?:number;readonly step?:number;readonly disabled?:boolean;readonly unstyled?:boolean}
/** Common axis entry preserves the two untouched floating coordinates. */
export function MotionVectorFields({label,value,onCommit,min=-1e9,max=1e9,step=1,disabled=false,unstyled=false}:MotionVectorFieldsProps){
 validateMotionVector(value,min,max);return <View style={{gap:6}}>{(['x','y','z'] as const).map(axis=><UnitInput key={axis} label={`${label} ${axis.toUpperCase()}`} value={value[axis]} min={min} max={max} step={step} precision={6} disabled={disabled} unstyled={unstyled} onCommit={number=>{if(disabled||number===value[axis])return;const next={...value,[axis]:number};validateMotionVector(next,min,max);onCommit(next);}}/>)}</View>;
}

import {View,type ViewProps} from 'react-native';
import {UnitInput} from '@/components/nyc-tron/ui/components/shell/UnitInput';
import {Button} from '@/components/nyc-tron/ui/components/Button';
import {MotionVectorFields} from '@/components/nyc-tron/ui/components/forge/motion/MotionVectorFields';
import {defaultMotionTransform,validateMotionTransform,type MotionTransform3D} from '@/components/nyc-tron/ui/components/forge/motion/motion-settings';
export type {MotionTransform3D,MotionVector3} from '@/components/nyc-tron/ui/components/forge/motion/motion-settings';
export interface Transform3DInspectorProps extends Omit<ViewProps,'children'> {readonly value:MotionTransform3D;readonly onCommit:(value:MotionTransform3D)=>void;readonly disabled?:boolean;readonly unstyled?:boolean}
/** Controlled scene/document transform; rotations retain complete turns. */
export function Transform3DInspector({value,onCommit,disabled=false,unstyled=false,...props}:Transform3DInspectorProps){
 validateMotionTransform(value);const set=(change:Partial<MotionTransform3D>)=>{if(disabled)return;const next={...value,...change};validateMotionTransform(next);onCommit(next);};
 return <View {...props} style={[{gap:10},props.style]}>
  {(['anchor','position','scale','rotation'] as const).map(key=><MotionVectorFields key={key} label={`3D ${key}`} value={value[key]} min={key==='scale'?-10000:key==='rotation'?-360000:-1e9} max={key==='scale'?10000:key==='rotation'?360000:1e9} step={key==='scale'?.01:1} disabled={disabled} unstyled={unstyled} onCommit={vector=>set({[key]:vector})}/>)}
  <UnitInput label="3D opacity" value={value.opacity} min={0} max={1} step={.01} disabled={disabled} unstyled={unstyled} onCommit={opacity=>set({opacity})}/>
  <Button title="Reset 3D transform" disabled={disabled} unstyled={unstyled} onPress={()=>{if(!disabled)onCommit(defaultMotionTransform());}}/>
 </View>;
}
